#include "resident/kernel/catalog_section_observation.hpp"
// 日期只从新作者明确条款和真实托回时刻计算；原型当前位置、远方接受和缓存不是许可。
#include "visit_appointment_catalog.hpp"
#include <set>
namespace hanmo::resident {namespace {
const VisitMessagePolicy* message(const VisitMessageCatalog& c,const StableId& id){for(const auto& p:c.policies)if(p.id==id)return &p;return nullptr;}
Status say(const InteractionCatalog& c,const VisitMessagePolicy& p,const StableId& id){const DialogueDefinition* d=nullptr;for(const auto& row:c.dialogues)if(row.id==p.dialogue_id){if(d)return common_failure("VisitAppointmentAmbiguousDialogue",id);d=&row;}if(!d||d->context_role!=p.role_id)return common_failure("VisitAppointmentCustodianDialogueRequired",id);const DialogueNode* n=nullptr;for(const auto& row:d->nodes)if(row.id==id){if(n)return common_failure("VisitAppointmentAmbiguousNode",id);n=&row;}return n&&n->kind=="say"&&(n->speaker=="$provider"||n->speaker==p.custodian_actor_id)&&!n->command?common_success():common_failure("VisitAppointmentCustodianDeclarationRequired",id);}
void unique(const BoundaryValue& v,const StableId& path){std::set<StableId> fields;for(const auto& f:boundary::object(v,path))if(!fields.insert(f.first).second)boundary::fail("DuplicateVisitAppointmentField",path+"/"+f.first);}
}
const VisitAppointmentPolicy* visit_appointment_policy(const VisitAppointmentCatalog& c,const StableId& id){for(const auto& p:c.policies)if(p.id==id)return &p;return nullptr;}
Status validate_visit_appointment_catalog(const VisitAppointmentCatalog& c,const VisitMessageCatalog& messages,const PersonalAppointmentCatalog& appointments,const InteractionCatalog& interaction,const VisitReplyCatalog* ordinary){
  // 只旁观本次原入口；返回值与首错仍由原函数独占。
  ::hanmo::resident::catalog_section_observation::Scope catalog_cost_observation(
      ::hanmo::resident::catalog_section_observation::Kind::catalog_validation, 60, "VisitAppointmentCatalog", "validate_visit_appointment_catalog", &c);

 auto valid=validate_visit_message_catalog(messages,interaction);if(!valid.ok)return valid;valid=validate_personal_appointment_catalog(appointments,interaction);if(!valid.ok)return valid;if(ordinary){valid=validate_visit_reply_catalog(*ordinary,messages,interaction);if(!valid.ok)return valid;}
 if((c.version!=1&&c.version!=2)||c.policies.empty()||c.policies.size()>4096)return common_failure("InvalidVisitAppointmentCatalog");if(c.version==2&&(messages.version<2||messages.version>3||appointments.version!=2))return common_failure("VisitAppointmentOriginalVersionMismatch");std::set<StableId> ids,originals;
 for(const auto& p:c.policies){const auto* m=message(messages,p.message_policy_id);const auto* a=personal_appointment_policy(appointments,p.appointment_policy_id);
  if(p.id.empty()||p.id.size()>256||!ids.insert(p.id).second||!originals.insert(p.message_policy_id).second||!m||!a||!p.inviter_commits_fixed_window||a->provider_actor_id!=m->recipient_actor_id||m->sender_actor_id==a->provider_actor_id||p.accept_before_offset<1||p.accept_before_offset>p.earliest_offset||p.earliest_offset<1||p.earliest_offset>p.latest_offset||p.latest_offset>720)return common_failure("InvalidVisitAppointmentPolicy",p.id);
  if(ordinary)for(const auto& r:ordinary->policies)if(r.message_policy_id==p.message_policy_id)return common_failure("VisitAppointmentOrdinaryReplyConflict",p.id);
  std::set<StableId> nodes{m->deposit_node_id,m->receive_node_id,m->withdraw_node_id};for(const auto& id:{p.offer_node_id,p.collect_node_id}){if(id.empty()||id.size()>256||!nodes.insert(id).second)return common_failure("VisitAppointmentDistinctDeclarationRequired",p.id);valid=say(interaction,*m,id);if(!valid.ok)return valid;}
 }
 return common_success();
}
Outcome<VisitAppointmentCatalog> decode_visit_appointment_catalog(const BoundaryValue& v,const VisitMessageCatalog& messages,const PersonalAppointmentCatalog& appointments,const InteractionCatalog& interaction,const VisitReplyCatalog* ordinary){try{using namespace boundary;unique(v,"visit_appointment_invitations");fields(v,{"version","policies"},{},"visit_appointment_invitations");VisitAppointmentCatalog c;c.version=get_int(v,"version","visit_appointment_invitations");const auto& rows=array(field(v,"policies","visit_appointment_invitations"),"policies");if(rows.size()>4096)fail("VisitAppointmentPolicyLimit","policies");for(const auto& row:rows){unique(row,"policy");fields(row,{"id","message_policy_id","appointment_policy_id","offer_node_id","collect_node_id","inviter_commits_fixed_window","accept_before_offset","earliest_offset","latest_offset"},{},"policy");VisitAppointmentPolicy p;p.id=get_string(row,"id","policy");p.message_policy_id=get_string(row,"message_policy_id","policy");p.appointment_policy_id=get_string(row,"appointment_policy_id","policy");p.offer_node_id=get_string(row,"offer_node_id","policy");p.collect_node_id=get_string(row,"collect_node_id","policy");p.inviter_commits_fixed_window=get_bool(row,"inviter_commits_fixed_window","policy");p.accept_before_offset=get_int(row,"accept_before_offset","policy");p.earliest_offset=get_int(row,"earliest_offset","policy");p.latest_offset=get_int(row,"latest_offset","policy");c.policies.push_back(std::move(p));}auto valid=validate_visit_appointment_catalog(c,messages,appointments,interaction,ordinary);return valid.ok?Outcome<VisitAppointmentCatalog>{true,std::move(c),{}}:Outcome<VisitAppointmentCatalog>{false,{},valid.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_visit_appointment_catalog(const VisitAppointmentCatalog& c){using V=BoundaryValue;V::Array rows;for(const auto& p:c.policies)rows.push_back(boundary::obj({{"id",V{p.id}},{"message_policy_id",V{p.message_policy_id}},{"appointment_policy_id",V{p.appointment_policy_id}},{"offer_node_id",V{p.offer_node_id}},{"collect_node_id",V{p.collect_node_id}},{"inviter_commits_fixed_window",V{p.inviter_commits_fixed_window}},{"accept_before_offset",V{p.accept_before_offset}},{"earliest_offset",V{p.earliest_offset}},{"latest_offset",V{p.latest_offset}}}));return boundary::obj({{"version",V{c.version}},{"policies",V{std::move(rows)}}});}
}
